package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void registered_member_can_be_fetched_by_id() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.name").value("김민지"))
                .andReturn().getResponse().getContentAsString();
        String memberId = objectMapper.readTree(registered).get("memberId").asText();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.name").value("김민지"));
    }

    @Test
    void registering_member_with_blank_name_returns_400() throws Exception {
        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"   \"}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void getting_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }
}
package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String bookId = registerBook("Clean Architecture");
        String memberId = registerMember("김민지");
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(bookId, memberId));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(bookId));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void member_cannot_borrow_more_than_five_books_at_once() throws Exception {
        String memberId = registerMember("이준호");
        for (int i = 0; i < 5; i++) {
            String bookId = registerBook("책 " + i);
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId))))
                    .andExpect(status().isCreated());
        }

        String sixthBookId = registerBook("책 6");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(sixthBookId, memberId))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void loaning_with_unregistered_member_returns_404() throws Exception {
        String bookId = registerBook("Effective Java");
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(bookId, UUID.randomUUID().toString()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isNotFound());
    }

    @Test
    void returning_a_loan_makes_the_book_available_again() throws Exception {
        String bookId = registerBook("Refactoring");
        String memberId = registerMember("박서준");
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").isNotEmpty());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId))))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String bookId = registerBook("Domain-Driven Design");
        String memberId = registerMember("최유나");
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returned_loans_do_not_count_toward_the_loan_limit() throws Exception {
        String memberId = registerMember("정하준");
        String firstLoanId = null;
        for (int i = 0; i < 5; i++) {
            String loanId = loanBook(registerBook("반납 테스트 " + i), memberId);
            if (firstLoanId == null) {
                firstLoanId = loanId;
            }
        }

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId))
                .andExpect(status().isOk());

        String sixthBookId = registerBook("반납 테스트 6");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(sixthBookId, memberId))))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void loan_with_loanedAt_is_due_fourteen_days_later() throws Exception {
        String bookId = registerBook("Pragmatic Programmer");
        String memberId = registerMember("강도윤");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBodyOn(bookId, memberId, "2026-01-01")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value("2026-01-01"))
                .andExpect(jsonPath("$.dueAt").value("2026-01-15"));
    }

    @Test
    void returning_on_the_due_date_has_no_late_fee() throws Exception {
        String loanId = loanBookOn(registerBook("기한 당일"), registerMember("서지안"), "2026-01-01");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-15\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_one_day_late_charges_100_won() throws Exception {
        String loanId = loanBookOn(registerBook("1일 연체"), registerMember("윤태별"), "2026-01-01");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-16\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void returning_five_days_late_charges_500_won() throws Exception {
        String loanId = loanBookOn(registerBook("5일 연체"), registerMember("임수빈"), "2026-01-01");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-20\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_body_uses_today_as_returnedAt() throws Exception {
        String loanId = loanBook(registerBook("오늘 반납"), registerMember("오세린"));

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returnedAt_before_loanedAt_returns_400() throws Exception {
        String loanId = loanBookOn(registerBook("날짜 역전"), registerMember("한이준"), "2026-01-01");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2025-12-31\"}"))
                .andExpect(status().isBadRequest());
